{
  "hechos": [
    {
      "id": "H1",
      "texto": "El municipio de La Esperanza del Norte estuvo dos días sin electricidad.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H2",
      "texto": "El origen del apagón fue un transformador averiado en la subestación Las Palmas.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H3",
      "texto": "Alrededor de 32.000 usuarios resultaron afectados por el corte de energía.",
      "paginas": ["P1", "P3"]
    },
    {
      "id": "H4",
      "texto": "En el barrio El Carmen, la junta de acción comunal contó 359 negocios que tuvieron pérdidas.",
      "paginas": ["P2"]
    },
    {
      "id": "H5",
      "texto": "En el barrio El Prado, la junta de acción comunal contó 355 negocios que tuvieron pérdidas.",
      "paginas": ["P4"]
    },
    {
      "id": "H6",
      "texto": "Carolina Cárdenas, líder comunal del barrio San José, contó a Crónica Andina que los comerciantes tuvieron que cerrar por falta de datáfonos.",
      "paginas": ["P2"]
    },
    {
      "id": "H7",
      "texto": "Luz Dary Avendaño, líder comunal del barrio Villa Nueva, contó a Diario Sabana que las noches fueron de completa oscuridad en el barrio.",
      "paginas": ["P3"]
    },
    {
      "id": "H8",
      "texto": "Sandra Cárdenas, líder comunal del barrio La Pradera, contó a Voz del Valle que se le dañó toda la comida de la nevera.",
      "paginas": ["P1"]
    },
    {
      "id": "H9",
      "texto": "En el barrio Las Brisas, la junta de acción comunal contó 141 negocios que tuvieron pérdidas.",
      "paginas": ["P1"]
    },
    {
      "id": "H10",
      "texto": "Un transformador temporal fue puesto en servicio mientras se repara el averiado.",
      "paginas": ["P4"]
    }
  ]
}
